#include "exercise.h"
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <math.h>
typedef struct {unsigned counts[5];int value;} price_memo;static price_memo*memo=NULL;static size_t memo_count=0;static int price(unsigned*c){for(size_t i=0;i<memo_count;i++)if(!memcmp(c,memo[i].counts,5*sizeof(unsigned)))return memo[i].value;int best=2147483647;bool any=false;for(unsigned mask=1;mask<32;mask++){bool ok=true;int k=0;for(int i=0;i<5;i++)if(mask&(1u<<i)){k++;if(!c[i])ok=false;}if(!ok)continue;any=true;for(int i=0;i<5;i++)if(mask&(1u<<i))c[i]--;int costs[]={0,800,1520,2160,2560,3000};int v=costs[k]+price(c);if(v<best)best=v;for(int i=0;i<5;i++)if(mask&(1u<<i))c[i]++;}int result=any?best:0;memo=(price_memo*)realloc(memo,(memo_count+1)*sizeof(price_memo));memcpy(memo[memo_count].counts,c,5*sizeof(unsigned));memo[memo_count++].value=result;return result;}double total(const unsigned*b,size_t n){unsigned c[5]={0};for(size_t i=0;i<n;i++){if(b[i]<1||b[i]>5)return -1;c[b[i]-1]++;}memo_count=0;double result=price(c);free(memo);memo=NULL;return result;}

